def _post_updates(post: Any, source: int) -> dict[str, z3.ExprRef]:
    reads = post.globals.get("_ghot_memory_reads", {})
    updates: dict[str, z3.ExprRef] = {}
    for name in GPR64:
        value = _resolve_memory_reads(
            claripy_to_z3(getattr(post.regs, name)),
            reads,
